import django.db.models.deletion
import django.utils.timezone
import tickets.models
from django.db import migrations, models


CATEGORIAS = {
    "agua": "mantencion",
    "electricidad": "mantencion",
    "infraestructura": "mantencion",
    "ruido": "convivencia",
}
ESTADOS = {
    "abierto": "Abierto", "en_revision": "En revisión", "resuelto": "Resuelto",
    "cerrado": "Cerrado", "cancelado": "Cerrado",
}
TIPOS = {"creado": "creado", "edicion": "edicion", "estado": "estado",
         "cancelacion": "estado", "asignacion": "asignado"}


def pasar_datos_de_gdc(apps, schema_editor):
    alias = schema_editor.connection.alias
    Ticket = apps.get_model("tickets", "Ticket")
    Historial = apps.get_model("tickets", "TicketHistorial")
    Evento = apps.get_model("tickets", "TicketEvento")
    Comentario = apps.get_model("tickets", "TicketComentario")

    for viejo, nuevo in CATEGORIAS.items():
        Ticket.objects.using(alias).filter(categoria=viejo).update(categoria=nuevo)

    for ticket in Ticket.objects.using(alias).iterator():
        if ticket.estado in ("cancelado", "cerrado"):
            ticket.estado = "cerrado"
            ticket.cerrado = ticket.resuelto or ticket.creado
        ticket.actualizado = ticket.resuelto or ticket.creado
        ticket.save(update_fields=["estado", "cerrado", "actualizado"])

    for h in Historial.objects.using(alias).order_by("creado", "id").iterator():
        if h.tipo == "respuesta":
            if h.usuario_id and h.detalle:
                c = Comentario.objects.using(alias).create(
                    ticket_id=h.ticket_id, autor_id=h.usuario_id, texto=h.detalle
                )
                Comentario.objects.using(alias).filter(pk=c.pk).update(creado=h.creado)
            continue
        tipo = TIPOS.get(h.tipo)
        if tipo is None:
            continue
        anterior = nuevo = ""
        if tipo == "estado":
            anterior = ESTADOS.get(h.estado_anterior, h.estado_anterior)
            nuevo = ESTADOS.get(h.estado_nuevo, h.estado_nuevo)
        elif tipo == "asignado":
            # gdc guardaba "Asignación actualizada: Nombre Apellido."
            nuevo = h.detalle.split(":", 1)[-1].strip().rstrip(".")
            nuevo = "" if nuevo == "Sin asignar" else nuevo[:100]
        e = Evento.objects.using(alias).create(
            ticket_id=h.ticket_id, autor_id=h.usuario_id, tipo=tipo, anterior=anterior, nuevo=nuevo
        )
        Evento.objects.using(alias).filter(pk=e.pk).update(creado=h.creado)


